<?php require_once __DIR__.'/../../config/seguranca.php';exigirAdmin();require_once __DIR__.'/../../includes/funcoes.php';require_once __DIR__.'/../../config/conexao.php';if($_SERVER['REQUEST_METHOD']!=='POST'||!validarCsrf(post('csrf')))redirect('admin/configuracoes/loja.php');$pdo=getPDO();$keys=['nome_loja','slogan','pix_chave','whatsapp','instagram','cidade','taxa_entrega'];try{$st=$pdo->prepare('INSERT INTO configuracoes(chave,valor) VALUES(?,?) ON DUPLICATE KEY UPDATE valor=VALUES(valor)');foreach($keys as $k)$st->execute([$k,trim((string)post($k))]);flash('sucesso','Configurações salvas.');}catch(Throwable $e){flash('erro','Não foi possível salvar as configurações.');}redirect('admin/configuracoes/loja.php');
